package com.yuegang.zhihui.common.mq;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;public final class JdbcOutboxDispatcher{private final JdbcTemplate jdbc;private final DomainEventPublisher publisher;private final String table;public JdbcOutboxDispatcher(JdbcTemplate j,DomainEventPublisher p,String table){if(!Set.of("order_outbox","wallet_outbox").contains(table))throw new IllegalArgumentException("unsupported outbox table");jdbc=j;publisher=p;this.table=table;}public int dispatch(){jdbc.update("UPDATE "+table+" SET status='RETRY',next_retry_at=NOW(6),claimed_at=NULL WHERE status='PROCESSING' AND claimed_at<DATE_SUB(NOW(6),INTERVAL 2 MINUTE)");List<Row>rows=jdbc.query("SELECT id,aggregate_id,event_type,payload_json FROM "+table+" WHERE status IN ('PENDING','RETRY') AND next_retry_at<=NOW(6) ORDER BY created_at LIMIT 50",(r,n)->new Row(r.getString(1),r.getString(2),r.getString(3),r.getString(4)));int sent=0;for(Row row:rows){if(jdbc.update("UPDATE "+table+" SET status='PROCESSING',claimed_at=NOW(6) WHERE id=? AND status IN ('PENDING','RETRY')",row.id())!=1)continue;try{publisher.publish(row.id(),row.aggregate(),row.type(),row.payload());jdbc.update("UPDATE "+table+" SET status='PUBLISHED',published_at=NOW(6),claimed_at=NULL,last_error=NULL WHERE id=?",row.id());sent++;}catch(RuntimeException e){String message=e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage());jdbc.update("UPDATE "+table+" SET status=CASE WHEN retry_count>=15 THEN 'FAILED' ELSE 'RETRY' END,retry_count=retry_count+1,next_retry_at=DATE_ADD(NOW(6),INTERVAL LEAST(300,POW(2,retry_count)) SECOND),claimed_at=NULL,last_error=? WHERE id=?",message.substring(0,Math.min(1000,message.length())),row.id());}}return sent;}private record Row(String id,String aggregate,String type,String payload){}}
